remediation.secureExample:
resource "aws_ebs_volume" "secure" {
  availability_zone = "us-east-1a"
  size              = 100
  encrypted         = true
  # kms_key_id     = "arn:aws:kms:..."  # Optional: customer-managed key
}

resource "aws_security_group" "ssh_access" {
  name        = "allow_ssh"
  description = "Allow SSH inbound from corporate network only"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]  # Replace with your corporate CIDR
  }
}

resource "aws_s3_bucket" "secure_bucket" {
  bucket = "my-secure-bucket"
  # No acl attribute - defaults to private
}

resource "aws_s3_bucket_public_access_block" "secure_bucket" {
  bucket = aws_s3_bucket.secure_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_db_instance" "secure" {
  # Use a variable instead of a hardcoded string
  password = var.db_password
}
